const D=window.ATLAS_DATA;
const $=(s,r=document)=>r.querySelector(s),$$=(s,r=document)=>[...r.querySelectorAll(s)];
const esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const decode=s=>{const e=document.createElement('textarea');e.innerHTML=s.replace(/#(\d+);/g,'&#$1;').replace(/#(quot|lt|gt|amp);/g,'&$1;');return e.value};
const app=$('#app');let view='overview',fileIndex=0,line=1,flowIndex=0,graphZoom=1,renderId=0,graphState=null,flowTimer=null,storyTimer=null,storyStep=0,scenario='add';
let codeTimer=null;let readLines=new Set();try{readLines=new Set(JSON.parse(localStorage.getItem('atlas-read')||'[]'))}catch{}
const names={cinema:'Dữ liệu chuyển động',overview:'Tổng quan',uml:'Bản đồ kiến trúc',flow:'Theo dấu luồng chạy',code:'Đọc từng dòng code',lab:'Phòng thực hành'};
const icons={Person:'◯',Student:'◈',Result:'◇',StudentManager:'▦',ResultManager:'⇄'};
const classes={
Person:{file:'models/person.py',title:'Thông tin của một người',text:'Lớp cha gom họ tên, ngày sinh, giới tính, số điện thoại và email. Student tái sử dụng các thuộc tính này bằng kế thừa.',notes:['Constructor gọi property setter để kiểm tra từng giá trị.','Không có mã sinh viên trong Person.','__str__ định nghĩa cách in thông tin cá nhân.']},
Student:{file:'models/student.py',title:'Một hồ sơ sinh viên',text:'Student kế thừa Person và thêm mã sinh viên, lớp, trạng thái. Một object tương ứng một sinh viên.',notes:['super().__init__ chạy constructor cha trên cùng object.','student_id chỉ có getter: không đổi mã tùy ý.','to_file_line xuất 8 cột dữ liệu sinh viên.']},
Result:{file:'models/result.py',title:'Kết quả của một môn học',text:'Giữ MSSV, mã/tên môn, học kỳ, tín chỉ và hai lần thi FE/RE. Trạng thái được tính động, không lưu riêng để sửa tay.',notes:['Điểm dùng float hoặc None, không làm tròn trước xét kết quả.','FE chưa có → status None → “Chưa có điểm”.','FE ≥ 5 hoặc FE < 5 và RE ≥ 5 → Pass.']},
StudentManager:{file:'services/student_manager.py',title:'Quản lý danh sách sinh viên',text:'Giữ list[Student]. Các method thực hiện thêm, cập nhật, tìm và lọc mà không gọi input() hay tự in menu.',notes:['find trả object gốc hoặc None khi không thấy.','add chặn trùng MSSV.','students trả bản sao nông của list, không clone object.']},
ResultManager:{file:'services/result_manager.py',title:'Quản lý danh sách kết quả',text:'Giữ list[Result] và tham chiếu StudentManager để kiểm tra sinh viên tồn tại, Active và bản ghi có trùng hay không.',notes:['Thêm/sửa điểm yêu cầu Active.','Bổ sung thông tin môn cho lịch sử không yêu cầu Active.','loading=True cho tải metadata thiếu; vẫn chặn khóa trùng.']}};
function stopTimers(){if(window.AtlasCinema)window.AtlasCinema.stop();clearInterval(codeTimer);codeTimer=null;clearInterval(flowTimer);flowTimer=null;clearInterval(storyTimer);storyTimer=null}
function title(n,t,p,extra=''){return `<div class="page-title"><div><div class="eyebrow"><i></i> CHƯƠNG ${n} / KHÁM PHÁ DỰ ÁN</div><h1>${t}</h1><p>${p}</p></div>${extra}</div>`}
function navigate(next){stopTimers();view=next in names?next:'overview';location.hash=view;$$('nav button').forEach(b=>b.classList.toggle('active',b.dataset.view===view));$('#crumb').textContent=names[view];$('#sidebar').classList.remove('open');app.className='fade-in';({cinema:()=>window.AtlasCinema.mount(),overview,uml,flow,code,lab}[view])();window.scrollTo({top:0,behavior:'instant'});bindNav();}
function bindNav(){ $$('[data-go]',app).forEach(b=>b.onclick=()=>navigate(b.dataset.go));}
function toast(text){$('#toast').textContent=text;$('#toast').classList.add('show');setTimeout(()=>$('#toast').classList.remove('show'),2400)}
function heroArt(){return `<div class="hero-visual" aria-label="Dữ liệu đi từ menu qua manager tới object"><svg viewBox="0 0 450 285" role="img"><defs><pattern id="dots" width="16" height="16" patternUnits="userSpaceOnUse"><circle cx="1" cy="1" r=".6" fill="#cbd5be"/></pattern><filter id="soft"><feDropShadow dx="0" dy="6" stdDeviation="8" flood-color="#526e35" flood-opacity=".07"/></filter></defs><rect x="10" y="5" width="430" height="270" fill="url(#dots)"/><ellipse cx="226" cy="263" rx="140" ry="12" fill="#e7ebdc" opacity=".5"/><path d="M 70 65 C 160 65 125 150 220 150 C 310 150 285 235 380 235" fill="none" stroke="#c8d4b6" stroke-width="1.5"/><path d="M 70 65 C 160 65 125 150 220 150 C 310 150 285 235 380 235" fill="none" stroke="#a3b48a" class="motion-line"/><circle class="dot-move" r="4"/><g class="hover-float" filter="url(#soft)"><rect x="24" y="25" width="134" height="72" rx="10" fill="#fff" stroke="#dfe6d3"/><rect x="37" y="38" width="23" height="23" rx="6" fill="#edf1e4"/><text x="49" y="54" text-anchor="middle" fill="#8ca173" font-size="15">⌘</text><text x="71" y="49" font-family="monospace" font-size="10" fill="#627955">menu.py</text><text x="38" y="79" font-family="monospace" font-size="8" fill="#a8b29c">input → validate</text></g><g filter="url(#soft)"><rect x="145" y="113" width="159" height="80" rx="10" fill="#fff" stroke="#bdcfa7"/><rect x="157" y="127" width="25" height="25" rx="6" fill="#e9efdf"/><text x="169" y="144" text-anchor="middle" fill="#799262" font-size="17">⇄</text><text x="192" y="138" font-family="monospace" font-size="10" fill="#627955">Manager</text><text x="159" y="174" font-family="monospace" font-size="8" fill="#9aa98a">find() · add() · update()</text><circle cx="286" cy="129" r="3" fill="#a6ba8b"/></g><g class="hover-float" style="animation-delay:-2s" filter="url(#soft)"><rect x="312" y="202" width="114" height="61" rx="9" fill="#fdfaf2" stroke="#e8d9bc"/><text x="327" y="225" font-family="monospace" font-size="10" fill="#ad895e">Result</text><text x="327" y="246" font-family="monospace" font-size="8" fill="#b09f83">status: Pass ✓</text></g><text x="331" y="62" font-family="monospace" font-size="8" fill="#a3b18e">class Student(Person)</text><text x="34" y="219" font-family="monospace" font-size="8" fill="#a3b18e">self._students = []</text></svg><div class="hero-caption">TỪ MỘT DÒNG CODE → MỘT HỆ THỐNG</div></div>`}
function overview(){app.innerHTML=`<section class="hero"><div><div class="eyebrow"><i></i> PFP191 · PYTHON, NHÌN THEO CÁCH KHÁC</div><h1>Đọc code.<br/><em>Nhìn thấy cách chạy.</em></h1><p>Một bản đồ tương tác của Student Management System. Đi từ bức tranh lớn đến từng dòng Python, cùng nhóm mình.</p><div class="actions"><button class="btn primary" data-go="cinema">Xem dữ liệu chuyển động <span>↗</span></button><button class="btn" data-go="uml">Xem bản đồ UML <span>↗</span></button></div></div>${heroArt()}</section><div class="stats"><div class="stat"><strong>05</strong><div><small>Class cốt lõi</small><span>MODEL & MANAGER</span></div></div><div class="stat"><strong>13</strong><div><small>File Python</small><span>TOÀN BỘ DỰ ÁN</span></div></div><div class="stat"><strong>95</strong><div><small>Hàm & method</small><span>FLOWCHART RIÊNG</span></div></div><div class="stat"><strong>838</strong><div><small>Dòng code</small><span>GIẢI THÍCH THEO DÒNG</span></div></div></div><div class="overview-split"><section><div class="section-head"><div><h2>Mỗi lần hiểu thêm một chút.</h2><p>Ba góc nhìn, một hệ thống.</p></div><span class="pill">LỘ TRÌNH GỢI Ý</span></div><div class="path-list"><div class="path-row" role="button" tabindex="0" data-go="uml"><span class="path-index">01</span><span class="path-icon">⬡</span><div><strong>Nhìn toàn cảnh</strong><small>Ai giữ dữ liệu? Các lớp liên kết thế nào?</small></div><span class="arrow">↗</span></div><div class="path-row" role="button" tabindex="0" data-go="flow"><span class="path-index">02</span><span class="path-icon">⇄</span><div><strong>Theo từng bước chạy</strong><small>Thử các nhánh if, vòng lặp và đường lỗi.</small></div><span class="arrow">↗</span></div><div class="path-row" role="button" tabindex="0" data-go="code"><span class="path-index">03</span><span class="path-icon">⌘</span><div><strong>Hiểu từng dòng Python</strong><small>Code thật và chú giải đặt cạnh nhau.</small></div><span class="arrow">↗</span></div></div></section><section><div class="section-head"><h2>Chuyện gì xảy ra khi…</h2><button class="text-link" data-go="lab">Thử thay đổi điểm ↗</button></div><div class="preview-panel"><div class="panel-label"><span>RESULT.PY / MỘT VÍ DỤ NHỎ</span><span class="live-tag">ĐANG MÔ PHỎNG</span></div><div class="mini-code"><div><span class="subtle">01 &nbsp;</span><b>fe</b> = <span id="demo-fe">4.0</span></div><div><span class="subtle">02 &nbsp;</span><b>re</b> = <span id="demo-re">5.0</span></div><div><span class="subtle">03 &nbsp;</span>status = Result.evaluate_status(fe, re)</div><div><span class="subtle">04 &nbsp;</span><b>print</b>(status) <span class="subtle">→</span> <span id="demo-return">"Pass"</span></div></div><div class="result-output"><span>Trạng thái được tính lại từ điểm</span><strong id="demo-status">Pass ✓</strong></div></div><p class="hint">Ví dụ FE đã có và dưới 5. Xem công thức đầy đủ trong Result.</p></section></div><div class="overview-note"><span>✳</span><div><strong>Được làm từ chính code của nhóm.</strong><br/>Bản chụp ngày 30.10.2026 · Chỉ mô phỏng để học, không thay đổi dữ liệu sinh viên thật.</div></div>`;
let n=0;storyTimer=setInterval(()=>{if(!$('#demo-fe'))return;const cases=[[4,5,'Pass ✓'],[3.5,4,'Fail'],[4,7.5,'Pass ✓']];const [fe,re,s]=cases[++n%3];$('#demo-fe').textContent=fe.toFixed(1);$('#demo-re').textContent=re.toFixed(1);$('#demo-status').textContent=s;$('#demo-return').textContent=s.startsWith('Pass')?'"Pass"':'"Fail"';$('.result-output').animate([{opacity:.3},{opacity:1}],{duration:500});},3200);$$('.path-row',app).forEach(r=>r.onkeydown=e=>{if(e.key==='Enter')navigate(r.dataset.go)});}
async function renderDiagram(source,onDone){const stage=$('#diagram-stage');const token=++renderId;graphZoom=1;stage.innerHTML='<div class="empty-state">Đang vẽ sơ đồ…</div>';try{const {svg}=await mermaid.render('atlasDiagram'+token,source);if(token!==renderId||!stage.isConnected)return;stage.innerHTML=svg;const svgNode=$('svg',stage);const vb=svgNode.viewBox.baseVal;svgNode.style.width=Math.max(vb.width,stage.clientWidth-50)+'px';svgNode.dataset.baseWidth=parseFloat(svgNode.style.width);$$('[data-zoom]').forEach(b=>b.onclick=()=>{graphZoom=b.dataset.zoom==='reset'?1:Math.max(.3,Math.min(3,graphZoom+Number(b.dataset.zoom)));svgNode.style.width=Number(svgNode.dataset.baseWidth)*graphZoom+'px'});if(onDone)onDone();}catch(e){if(token===renderId)stage.innerHTML=`<div class="diagram-error">Chưa vẽ được sơ đồ. Bạn vẫn có thể đọc code và chú giải.<br/>${esc(e.message)}</div>`;}}
function diagramBar(name){return `<div class="diagram-bar"><span>${esc(name)}</span><div class="tools"><button class="icon-btn" data-zoom="-.2" aria-label="Thu nhỏ">−</button><button class="icon-btn" data-zoom="reset" aria-label="Khôi phục tỷ lệ">⤢</button><button class="icon-btn" data-zoom=".2" aria-label="Phóng to">+</button></div></div>`}
function uml(){app.innerHTML=title('02','Bản đồ của cả hệ thống.','Chọn một lớp để hiểu trách nhiệm, dữ liệu và mối liên kết. Sơ đồ giữ đúng cấu trúc OOP trong dự án.','<span class="pill">5 CLASS / 3 TẦNG</span>')+`<div class="toolbar">${Object.keys(classes).map(n=>`<button class="class-chip" data-class="${n}">${icons[n]} ${n}</button>`).join('')}</div><div class="diagram-layout wide-diagram"><section class="diagram-panel">${diagramBar('UML / CLASS DIAGRAM')}<div class="diagram-stage" id="diagram-stage"></div></section><aside class="inspector" id="class-inspector"></aside></div><p class="hint">Mũi tên tam giác rỗng: kế thừa · Hình thoi rỗng: giữ danh sách object · Mũi tên thường: sử dụng / tham chiếu.<br/>Thuộc tính _... là quy ước nội bộ của Python, không phải cơ chế bảo mật tuyệt đối.</p>`;
$$('[data-class]').forEach(b=>b.onclick=()=>selectClass(b.dataset.class));selectClass('Student');renderDiagram(D.uml,()=>{$$('.node,.classGroup', $('#diagram-stage')).forEach(n=>n.onclick=()=>{const name=Object.keys(classes).sort((a,b)=>b.length-a.length).find(k=>(n.id||'').includes(k));if(name)selectClass(name)})});}
function selectClass(name){const c=classes[name];$$('[data-class]').forEach(b=>b.classList.toggle('active',b.dataset.class===name));$('#class-inspector').innerHTML=`<div class="kicker">${esc(c.file)}</div><h3>${name}</h3><span class="pill">${c.title}</span><p>${c.text}</p><ul>${c.notes.map(t=>`<li>${t}</li>`).join('')}</ul><div class="annotation">${name==='Student'?'Student là một Person có thêm thông tin học tập. super() khởi tạo trên cùng object, không tạo một Person riêng.':name==='Result'?'Status là property chỉ đọc. Không có setter để gán tay Pass hoặc Fail.':'Manager và model không tự gọi input(). Phần nhận dữ liệu nằm ở menu.'}</div><button class="btn" id="open-class-code">Mở code của lớp này ↗</button>`;$('#open-class-code').onclick=()=>openCode(c.file,1);}
function optionsFiles(selected){return D.files.map((f,i)=>`<option value="${i}" ${i===selected?'selected':''}>${f.name}</option>`).join('')}
function flow(){const g=D.graphs[flowIndex];fileIndex=D.files.findIndex(f=>f.name===g.file);app.innerHTML=title('03','Theo dấu từng bước chạy.','Chọn hàm, bấm chạy và quan sát đường đi. Ở mỗi điều kiện, bạn có thể tự chọn nhánh để khám phá.','<span class="pill">95 SƠ ĐỒ</span>')+`<div class="toolbar"><select id="flow-file" class="select" aria-label="File flowchart">${optionsFiles(fileIndex)}</select><select id="flow-function" class="select" aria-label="Chọn hàm">${flowFunctionOptions(g.file)}</select><button class="btn" id="flow-source">Đọc code ↗</button></div><p class="flow-info">${esc(g.description)}</p><div class="diagram-layout"><section class="diagram-panel">${diagramBar(g.file+' / '+g.name)}<div class="diagram-stage" id="diagram-stage"></div><div class="player"><button class="icon-btn" id="flow-reset" aria-label="Chạy lại từ đầu">↺</button><button class="btn primary" id="flow-play">▷ Tự chạy</button><button class="btn" id="flow-next">Bước tiếp →</button><select id="flow-speed" class="select" aria-label="Tốc độ animation"><option value="1600">Chậm</option><option value="900" selected>Vừa</option><option value="450">Nhanh</option></select><span class="player-label" id="flow-count">SẴN SÀNG</span></div></section><aside class="inspector"><div class="kicker">BẠN ĐANG Ở ĐÂU?</div><h3 id="node-title">Điểm bắt đầu</h3><code id="node-code">${esc(g.name)}()</code><p id="node-explain">Nhấn “Bước tiếp” để theo từng câu lệnh. Tại nhánh if, hãy chọn Đúng hoặc Sai theo dữ liệu muốn thử.</p><div class="branch-actions" id="branch-actions"></div><div class="annotation">Sơ đồ mô tả luồng điều khiển, không thực thi Python. Tự chạy đi theo nhánh đầu tiên; bạn có thể tạm dừng và chọn nhánh khác. Vòng lặp sẽ tiếp tục đến khi chọn đường thoát.</div></aside></div>`;
$('#flow-file').onchange=e=>{const f=D.files[+e.target.value];const i=D.graphs.findIndex(g=>g.file===f.name);if(i<0){toast('File package này chỉ xuất tên, không có hàm.');e.target.value=fileIndex;return}flowIndex=i;clearInterval(flowTimer);flow()};$('#flow-function').onchange=e=>{flowIndex=+e.target.value;clearInterval(flowTimer);flow()};$('#flow-source').onclick=()=>openCode(g.file,g.start);$('#flow-reset').onclick=()=>{pauseFlow();initGraph(g)};$('#flow-play').onclick=toggleFlow;$('#flow-next').onclick=()=>{pauseFlow();stepGraph()};renderDiagram(g.graph,()=>{initGraph(g);$$('.node',$('#diagram-stage')).forEach(n=>n.onclick=()=>{pauseFlow();const id=n.id.match(/^flowchart-(n\d+)-/)?.[1];if(id){graphState.current=id;showNode()}})});}
function flowFunctionOptions(file){return D.graphs.map((g,i)=>g.file===file?`<option value="${i}" ${i===flowIndex?'selected':''}>${g.name} · L${g.start}${g.heading.includes('setter')?' · setter':g.heading.includes('getter')?' · getter':''}</option>`:'').join('')}
function initGraph(g){const nodes={},edges=[];for(const row of g.graph.split('\n')){let n=row.match(/^\s*(n\d+)(?:\[|\{|\().*?"(.*?)"/);if(n)nodes[n[1]]=decode(n[2]).replace(/<br\/?\s*>/g,' ');let e=row.match(/^\s*(n\d+)\s+(-->|-\.->)(?:\|([^|]*)\|)?\s+(n\d+)/);if(e)edges.push({from:e[1],to:e[4],label:e[3]||'Tiếp tục',error:e[2]==='-.->'});}const start=Object.keys(nodes).find(n=>nodes[n].startsWith('Gọi '));graphState={nodes,edges,current:start,visited:[],count:0,g};showNode()}
function domNode(id){return $$('.node',$('#diagram-stage')).find(n=>n.id.startsWith('flowchart-'+id+'-'))}
function showNode(){if(!graphState)return;const s=graphState;$$('.node',$('#diagram-stage')).forEach(n=>n.classList.remove('active','visited'));for(const id of s.visited)domNode(id)?.classList.add('visited');const activeNode=domNode(s.current);activeNode?.classList.add('active');if(activeNode){const stage=$('#diagram-stage');const a=activeNode.getBoundingClientRect(),b=stage.getBoundingClientRect();stage.scrollBy({top:a.top-b.top-stage.clientHeight/2+a.height/2,left:a.left-b.left-stage.clientWidth/2+a.width/2,behavior:'smooth'});}const txt=s.nodes[s.current]||'Kết thúc';const m=txt.match(/^L(\d+):\s*(.*)/);$('#node-title').textContent=m?'Dòng '+m[1]:txt;$('#node-code').textContent=m?m[2]:s.g.name+'()';const f=D.files.find(f=>f.name===s.g.file);$('#node-explain').textContent=m?(f.notes[m[1]]||'Tiếp tục theo nhánh được chọn.'):txt.includes('Lỗi')?'Ngoại lệ truyền về hàm gọi. Tìm except phù hợp ở menu hoặc main.':txt.includes('Trả về')?'Hàm kết thúc. Chương trình tiếp tục tại nơi đã gọi hàm này.':'Bắt đầu gọi hàm với các tham số từ nơi gọi.';$('#flow-count').textContent='BƯỚC '+String(s.count).padStart(2,'0');const edges=s.edges.filter(e=>e.from===s.current);$('#branch-actions').innerHTML=edges.length>1?edges.map((e,i)=>`<button data-edge="${i}">${esc(e.label)} ${e.error?'↗':'→'}</button>`).join(''):'';$$('[data-edge]').forEach(b=>b.onclick=()=>{pauseFlow();stepGraph(+b.dataset.edge)});if(!edges.length)pauseFlow();}
function stepGraph(index=0){if(!graphState)return;const s=graphState,edges=s.edges.filter(e=>e.from===s.current);if(!edges.length){toast('Đã đến cuối đường đi. Bấm ↺ để chạy lại.');return}const e=edges[index]||edges[0];s.visited.push(s.current);s.current=e.to;s.count++;showNode();if(s.count>150){pauseFlow();toast('Đã tạm dừng vòng lặp. Hãy chọn nhánh thoát.')}}
function pauseFlow(){clearInterval(flowTimer);flowTimer=null;if($('#flow-play'))$('#flow-play').textContent='▷ Tự chạy'}
function toggleFlow(){if(flowTimer){pauseFlow();return}if(!graphState)return;$('#flow-play').textContent='Ⅱ Tạm dừng';flowTimer=setInterval(()=>stepGraph(),Number($('#flow-speed').value));stepGraph()}

function highlight(src){const re=/("(?:\\.|[^"\\])*"|'(?:\\.|[^'\\])*'|\b(?:def|class|return|if|elif|else|for|while|in|not|and|or|is|None|True|False|from|import|try|except|raise|with|as|continue|lambda)\b|\b\d+(?:\.\d+)?\b)/g;let out='',last=0;for(const m of src.matchAll(re)){out+=esc(src.slice(last,m.index));const v=m[0];out+=`<span class="${/^['"]/.test(v)?'tok-str':/^\d/.test(v)?'tok-num':'tok-kw'}">${esc(v)}</span>`;last=m.index+v.length}return out+esc(src.slice(last))}
function openCode(file,ln){fileIndex=D.files.findIndex(f=>f.name===file);if(fileIndex<0)fileIndex=0;line=ln;navigate('code');requestAnimationFrame(()=>selectLine(line,true))}
function code(){clearInterval(codeTimer);codeTimer=null;const f=D.files[fileIndex];line=Math.min(Math.max(line,1),f.lines.length);app.innerHTML=title('04','Một dòng, một điều hiểu rõ.','Chạm vào từng dòng để xem giải thích. Bạn đang đọc nguyên bản source, không phải code minh họa.','<span class="pill">SOURCE / 30.10.2026</span>')+`<div class="toolbar"><select id="code-file" class="select" aria-label="Chọn file Python">${optionsFiles(fileIndex)}</select><select id="code-function" class="select" aria-label="Đi tới hàm"><option value="1">Từ đầu file</option>${f.functions.map(n=>`<option value="${n.start}">${n.name} · ${n.kind} · L${n.start}</option>`).join('')}</select><input class="input" id="code-search" placeholder="Tìm trong file…" aria-label="Tìm trong file"><button class="btn" id="code-search-next">Tìm →</button></div><div class="code-auto"><span class="live-tag">ĐỌC CODE CÙNG ANIMATION</span><button class="btn primary" id="code-play">▷ Giải thích tự động</button><button class="btn" id="code-restart">↺ Về đầu file</button><select id="code-speed" class="select" aria-label="Tốc độ đọc code"><option value="5000">Chậm · 5 giây/dòng</option><option value="3000" selected>Vừa · 3 giây/dòng</option><option value="1200">Nhanh · 1,2 giây/dòng</option></select><span class="hint">Mỗi dòng sáng lên cùng lời giải thích.</span></div><div class="code-layout"><section class="code-window"><div class="window-bar"><span class="window-dots"><i></i><i></i><i></i></span>${esc(f.name)}<span style="margin-left:auto">${f.lines.length} dòng</span></div><div class="code-scroll" id="code-scroll">${f.lines.map((s,i)=>`<div class="code-line" data-line="${i+1}" role="button" tabindex="0" aria-label="Dòng ${i+1}: ${esc(s)}"><span class="ln">${i+1}</span><span class="code-text">${highlight(s)||' '}</span></div>`).join('')}</div></section><aside class="inspector"><div class="kicker">GIẢI THÍCH THEO DÒNG</div><div class="explain-number" id="explain-number"></div><code id="explain-snippet"></code><p id="line-explain"></p><div class="read-progress"><span id="read-progress"></span></div><div class="small-nav"><button class="btn" id="prev-line">← Trước</button><button class="btn" id="next-line">Tiếp →</button></div><button class="btn" id="code-to-flow">Xem flowchart của hàm ↗</button><p class="hint" id="code-context"></p><p class="hint" id="read-count"></p></aside></div><section class="glossary"><div class="section-head"><h2>Gỡ rối một chút cú pháp.</h2><span class="file-badge">PYTHON / QUICK NOTES</span></div><div class="glossary-grid">${D.glossary.slice(0,10).map(g=>`<article class="glossary-item"><code>${esc(g.key)}</code><p>${esc(g.text)}</p></article>`).join('')}</div><button class="btn" id="show-glossary" style="margin-top:14px">Xem thêm khái niệm ↓</button></section>`;
$('#code-play').onclick=()=>{if(codeTimer){pauseCode();return}$('#code-play').textContent='Ⅱ Tạm dừng';codeTimer=setInterval(()=>{if(line>=f.lines.length){pauseCode();toast('Đã đi hết file. Chọn file tiếp theo để học tiếp.');return}let next=line+1;while(next<f.lines.length&&!f.lines[next-1].trim())next++;selectLine(next,true)},Number($('#code-speed').value));};$('#code-restart').onclick=()=>{pauseCode();selectLine(1,true)};$('#code-file').onchange=e=>{fileIndex=+e.target.value;line=1;code()};$('#code-function').onchange=e=>selectLine(+e.target.value,true);$$('[data-line]').forEach(r=>{r.onclick=()=>{pauseCode();selectLine(+r.dataset.line)};r.onkeydown=e=>{if(e.key==='Enter')selectLine(+r.dataset.line)}});$('#prev-line').onclick=()=>selectLine(Math.max(1,line-1),true);$('#next-line').onclick=()=>selectLine(Math.min(f.lines.length,line+1),true);const search=()=>{const q=$('#code-search').value.toLowerCase();if(!q)return;const found=f.lines.findIndex((s,i)=>i>=line&&s.toLowerCase().includes(q));const fallback=found>=0?found:f.lines.findIndex(s=>s.toLowerCase().includes(q));if(fallback>=0)selectLine(fallback+1,true);else toast('Không tìm thấy trong file này.')};$('#code-search-next').onclick=search;$('#code-search').onkeydown=e=>{if(e.key==='Enter')search()};$('#code-to-flow').onclick=()=>{const fun=f.functions.find(n=>n.start<=line&&line<=n.end);const i=D.graphs.findIndex(g=>g.file===f.name&&g.start===(fun?.start));if(i>=0){flowIndex=i;navigate('flow')}else toast('Chọn một dòng trong thân hàm để mở flowchart.')};$('#show-glossary').onclick=()=>{$('.glossary-grid').innerHTML=D.glossary.map(g=>`<article class="glossary-item"><code>${esc(g.key)}</code><p>${esc(g.text)}</p></article>`).join('');$('#show-glossary').remove()};selectLine(line);}
function pauseCode(){clearInterval(codeTimer);codeTimer=null;if($('#code-play'))$('#code-play').textContent='▷ Giải thích tự động'}
function selectLine(n,scroll=false){line=n;const f=D.files[fileIndex];$$('.code-line').forEach(r=>r.classList.toggle('selected',+r.dataset.line===n));$('#explain-number').textContent=String(n).padStart(2,'0');$('#explain-snippet').textContent=f.lines[n-1]||'(dòng trống)';$('#line-explain').animate([{opacity:.3,transform:'translateY(5px)'},{opacity:1,transform:'translateY(0)'}],{duration:350});$('#line-explain').textContent=f.notes[n]||'Dòng trống phân cách các khối code cho dễ đọc, không tạo thao tác xử lý.';const fun=f.functions.find(x=>x.start<=n&&n<=x.end);$('#code-context').textContent=fun?`Trong ${fun.name} · ${fun.kind} · dòng ${fun.start}–${fun.end}`:'Khai báo ở cấp module. Chưa nằm trong thân hàm.';readLines.add(f.name+':'+n);try{localStorage.setItem('atlas-read',JSON.stringify([...readLines]))}catch{}const read=f.lines.filter((_,i)=>readLines.has(f.name+':'+(i+1))).length;$('#read-progress').style.width=read/f.lines.length*100+'%';$('#read-count').textContent=`Đã ghé ${read}/${f.lines.length} dòng trong file này. Tiến độ chỉ lưu trên trình duyệt của bạn.`;if(scroll){const r=$(`[data-line="${n}"]`);const box=$('#code-scroll');box.scrollTo({top:r.offsetTop-box.offsetTop-box.clientHeight/3,behavior:'smooth'})}}
const scenarios={
add:{title:'Thêm một kết quả mới',sub:'Một lần nhập điểm đi qua những đâu?',steps:[
['Nhập MSSV và xác nhận sinh viên','Menu gọi check_student. StudentManager.find trả Student Active.','result_management.py',31,{student_id:'SE211528'},'Student tồn tại · status Active'],
['Nhập mã môn, kiểm tra khóa trùng','Tìm cặp MSSV + mã môn. Không có bản ghi cũ thì đi tiếp.','result_management.py',36,{course_id:'PFP191'},'find(...) → None'],
['Nhập thông tin môn và điểm','Tên môn, học kỳ và tín chỉ qua validator; FE dưới 5 nên nhập RE.','result_management.py',40,{course_name:'Programming Fundamentals…',semester:'Fall2026',credits:3,grade_fe:4,grade_re:5},'validate_score(4), validate_score(5)'],
['Tạo object Result','Constructor gọi các property setter. Dữ liệu hợp lệ mới tạo object thành công.','models/result.py',7,{object:'Result'},'Result(...) → object mới'],
['Manager kiểm tra và thêm vào list','Kiểm tra lại kiểu object, metadata, sinh viên và trùng khóa rồi append.','services/result_manager.py',31,{list_size:1},'_results.append(result)'],
['Đọc result_status → Pass','Property tính lại từ FE=4, RE=5. Chưa ghi file; dữ liệu mới chỉ ở bộ nhớ.','models/result.py',72,{result_status:'Pass'},'FE < 5 và RE ≥ 5 → Pass ✓'],
['Chọn Save and Exit','main gọi to_file_line rồi ghi file. Mô phỏng này không ghi dữ liệu thật.','main.py',12,{persisted:'Chỉ mô phỏng'},'student_id|course_id|…|4.0|5.0|Pass']
]},
update:{title:'Sửa điểm và thấy status đổi',sub:'FE mới đạt thì RE cũ đi đâu?',steps:[
['Bắt đầu từ kết quả cũ','Object đang có FE=4, RE=5 nên status Pass.','models/result.py',82,{student_id:'SE211528',course_id:'PFP191',grade_fe:4,grade_re:5,result_status:'Pass'},'Kết quả ban đầu'],
['Tìm sinh viên và kết quả','Sửa điểm yêu cầu Student Active và bản ghi tồn tại.','services/result_manager.py',43,{},'check_student → find'],
['Kiểm tra FE/RE mới vào biến tạm','FE mới là 6, RE không cần nhập. Kiểm tra trước để tránh cập nhật một nửa.','services/result_manager.py',48,{pending_fe:6,pending_re:null},'fe = validate_score(6)'],
['FE từ 5 trở lên → xóa RE','Manager gán re=None dù trước đó đã có điểm thi lại.','services/result_manager.py',50,{pending_re:null},'re = None'],
['Gán property điểm mới','Các setter xác thực giá trị rồi đổi trạng thái object.','services/result_manager.py',52,{grade_fe:6,grade_re:null},'result.grade_fe = fe; result.grade_re = re'],
['Đọc status → Pass','FE=6 đã đạt, không cần RE. Status là giá trị tính động, không có biến status riêng phải sửa.','models/result.py',72,{result_status:'Pass'},'FE ≥ 5 → Pass ✓']
]},
ungraded:{title:'Chưa có FE không có nghĩa là 0',sub:'Phân biệt chưa chấm và thi trượt.',steps:[
['Nhập thông tin môn hợp lệ','Đã biết môn, học kỳ và tín chỉ; chưa nhập điểm.','result_management.py',23,{student_id:'SE211528',course_id:'PFP191',credits:3,semester:'Fall2026'},'Thông tin môn đã có'],
['Bỏ trống FE','input_score cho phép trống, trả None chứ không trả 0.','utils/validator.py',110,{grade_fe:null},'raw rỗng → return None'],
['Không hỏi RE','Điều kiện fe is not None and fe < 5 là sai. RE giữ None.','result_management.py',18,{grade_re:null},'Không thực hiện phép so sánh None < 5'],
['Tính result_status','Nhánh đầu của evaluate_status phát hiện FE None và trả None.','models/result.py',75,{result_status:null},'return None'],
['Hiển thị “Chưa có điểm”','__str__ đổi None thành chữ dễ hiểu. Khi ghi file sẽ để ô điểm/status trống.','models/result.py',106,{display:'Chưa có điểm'},'None ≠ 0 ≠ Fail']
]}};
function lab(){const s=scenarios[scenario];app.innerHTML=title('05','Cho code chuyển động.','Thử một tình huống cụ thể. Mỗi bước làm sáng đường đi và cho thấy object trong bộ nhớ thay đổi.','<span class="pill">MÔ PHỎNG AN TOÀN</span>')+`<div class="tabs">${Object.entries(scenarios).map(([k,s])=>`<button data-scenario="${k}" class="${k===scenario?'active':''}">${k==='add'?'Thêm kết quả':k==='update'?'Sửa điểm':'Chưa có điểm'}</button>`).join('')}</div><div class="section-head"><div><h2>${s.title}</h2><p>${s.sub}</p></div><div class="page-nav-row"><button class="icon-btn" id="story-reset" aria-label="Bắt đầu lại">↺</button><button class="btn primary" id="story-play">▷ Phát animation</button></div></div><div class="learning-layout"><div class="story-list">${s.steps.map((st,i)=>`<div class="story-step" data-step="${i}" role="button" tabindex="0"><span class="step-dot">${i+1}</span><div><strong>${st[0]}</strong><p>${st[1]}</p><code>${st[2]} : ${st[3]} ↗</code></div></div>`).join('')}</div><section class="object-panel"><div class="object-header"><strong>◈ Dữ liệu & object mô phỏng</strong><span class="live-tag">TRỰC TIẾP</span></div><div class="object-rows" id="object-rows"></div><div class="terminal" id="story-terminal"></div><div class="player" style="border:0;padding:17px 0 0"><button class="btn" id="story-prev">← Trước</button><button class="btn" id="story-next">Tiếp →</button><span class="player-label" id="story-counter"></span></div><button class="btn" id="story-source" style="width:100%;justify-content:center;margin-top:12px">Đọc dòng code này ↗</button><p class="hint">Dữ liệu minh họa. Không chạy Python và không thay đổi file của dự án.</p></section></div><section class="grade-lab"><h2>Tự thử công thức Pass / Fail.</h2><p>Kéo điểm để xem kết quả thay đổi. Quy tắc giống Result.evaluate_status trong source.</p><div class="grade-controls"><div><label for="fe-slider">FINAL EXAM · FE <span class="value" id="fe-value">4.0</span></label><input id="fe-slider" type="range" min="0" max="10" step="0.1" value="4"><label class="checkbox"><input type="checkbox" id="fe-empty"> Chưa có FE</label></div><div><label for="re-slider">RETAKE EXAM · RE <span class="value" id="re-value">5.0</span></label><input id="re-slider" type="range" min="0" max="10" step="0.1" value="5"><label class="checkbox"><input type="checkbox" id="re-empty"> Chưa có RE</label></div><div class="grade-result" id="grade-result">Pass ✓</div></div><div class="annotation" id="grade-rule">FE dưới 5, RE từ 5 trở lên → Pass.</div></section><section class="quiz"><div class="eyebrow"><i></i> KIỂM TRA NHANH</div><div class="quiz-question">Đã thêm Result vào manager, dữ liệu có được lưu xuống file ngay chưa?</div><div class="quiz-answers"><button class="btn" data-answer="wrong">Có, append là lưu file</button><button class="btn" data-answer="right">Chưa, mới ở trong bộ nhớ</button></div><div class="quiz-feedback" id="quiz-feedback" role="status"></div></section>`;
$$('[data-scenario]').forEach(b=>b.onclick=()=>{clearInterval(storyTimer);storyTimer=null;scenario=b.dataset.scenario;storyStep=0;lab()});$$('[data-step]').forEach(b=>{b.onclick=()=>{pauseStory();setStory(+b.dataset.step)};b.onkeydown=e=>{if(e.key==='Enter'){pauseStory();setStory(+b.dataset.step)}}});$('#story-reset').onclick=()=>{pauseStory();setStory(0)};$('#story-play').onclick=()=>{if(storyTimer){pauseStory();return}if(storyStep>=s.steps.length-1)setStory(0);$('#story-play').textContent='Ⅱ Tạm dừng';storyTimer=setInterval(()=>{if(storyStep>=s.steps.length-1){pauseStory();return}setStory(storyStep+1)},2200)};$('#story-prev').onclick=()=>{pauseStory();setStory(Math.max(0,storyStep-1))};$('#story-next').onclick=()=>{pauseStory();setStory(Math.min(s.steps.length-1,storyStep+1))};$('#story-source').onclick=()=>openCode(s.steps[storyStep][2],s.steps[storyStep][3]);['fe-slider','re-slider','fe-empty','re-empty'].forEach(id=>$('#'+id).oninput=gradeUpdate);$$('[data-answer]').forEach(b=>b.onclick=()=>{$('#quiz-feedback').textContent=b.dataset.answer==='right'?'Đúng rồi. append chỉ đổi list trong bộ nhớ. main.save_data mới gọi File I/O khi lưu.':'Chưa đúng: append thêm object vào list. Việc ghi file chỉ diễn ra khi gọi save_data.'});setStory(Math.min(storyStep,s.steps.length-1));gradeUpdate();}
function pauseStory(){clearInterval(storyTimer);storyTimer=null;if($('#story-play'))$('#story-play').textContent='▷ Phát animation'}
function setStory(n){storyStep=n;const s=scenarios[scenario],obj={};s.steps.slice(0,n+1).forEach(st=>Object.assign(obj,st[4]));$$('[data-step]').forEach(b=>{b.classList.toggle('current',+b.dataset.step===n);b.classList.toggle('past',+b.dataset.step<n)});$('#object-rows').innerHTML=Object.entries(obj).map(([k,v])=>`<div class="object-row ${k in s.steps[n][4]?'new':''}"><span class="object-key">${k}</span><span class="object-value">${v===null?'None':typeof v==='number'?Number.isInteger(v)&&k.includes('grade')?v+'.0':v:esc(v)}</span></div>`).join('');$('#story-terminal').innerHTML=`<span class="prompt">&gt; bước ${n+1}</span><br/>${esc(s.steps[n][5])}`;$('#story-counter').textContent=`${n+1} / ${s.steps.length}`;$('#story-prev').disabled=n===0;$('#story-next').disabled=n===s.steps.length-1;}
function gradeUpdate(){const noFE=$('#fe-empty').checked;const fe=Number($('#fe-slider').value);const reAllowed=!noFE&&fe<5;$('#re-slider').disabled=!reAllowed||$('#re-empty').checked;$('#re-empty').disabled=!reAllowed;$('#fe-slider').disabled=noFE;const re=(!reAllowed||$('#re-empty').checked)?null:Number($('#re-slider').value);const status=noFE?null:fe>=5||(re!==null&&re>=5)?'Pass':'Fail';$('#fe-value').textContent=noFE?'None':fe.toFixed(1);$('#re-value').textContent=re===null?'None':re.toFixed(1);$('#grade-result').textContent=status===null?'Chưa có điểm':status==='Pass'?'Pass ✓':'Fail';$('#grade-result').style.color=status==='Fail'?'#b18864':'#7a935f';$('#grade-rule').textContent=noFE?'FE chưa có → status None, không kết luận thi trượt.':fe>=5?'FE đã từ 5 trở lên → Pass. Theo luồng menu/manager, RE được xóa.':re!==null&&re>=5?'FE dưới 5, RE từ 5 trở lên → Pass.':'FE dưới 5 và RE trống hoặc dưới 5 → Fail.';}
function openSearch(){const dlg=$('#search-dialog');if(!dlg.open)dlg.showModal();$('#global-search').focus();searchGlobal('')}
function searchGlobal(q){q=q.toLowerCase().trim();const hits=[];for(let i=0;i<D.files.length;i++){const f=D.files[i];if(!q||f.name.toLowerCase().includes(q))hits.push({title:f.name,sub:f.lines.length+' dòng · Mở file',i,line:1});if(q)for(const fn of f.functions)if(fn.name.toLowerCase().includes(q))hits.push({title:fn.name+' · '+fn.kind,sub:f.name+' : '+fn.start,i,line:fn.start});if(q&&hits.length<20){const n=f.lines.findIndex(l=>l.toLowerCase().includes(q));if(n>=0&&!hits.some(h=>h.i===i&&h.line===n+1))hits.push({title:f.lines[n].trim(),sub:f.name+' : '+(n+1),i,line:n+1})}}$('#search-results').innerHTML=hits.length?hits.slice(0,25).map((h,i)=>`<button class="search-item" data-hit="${i}"><strong>${esc(h.title)}</strong><small>${esc(h.sub)}</small></button>`).join(''):'<div class="search-empty">Chưa tìm thấy. Thử “grade”, “Student” hoặc “None”.</div>';$$('[data-hit]').forEach(b=>b.onclick=()=>{const h=hits[+b.dataset.hit];$('#search-dialog').close();openCode(D.files[h.i].name,h.line)})}
$$('nav button').forEach(b=>b.onclick=()=>navigate(b.dataset.view));$('.mobile-toggle').onclick=()=>$('#sidebar').classList.toggle('open');$('#search-trigger').onclick=openSearch;$('#close-search').onclick=()=>$('#search-dialog').close();$('#global-search').oninput=e=>searchGlobal(e.target.value);$('#search-dialog').onclick=e=>{if(e.target===$('#search-dialog'))$('#search-dialog').close()};document.addEventListener('keydown',e=>{if(e.key==='/'&&!['INPUT','TEXTAREA','SELECT'].includes(document.activeElement.tagName)){e.preventDefault();openSearch()}if(e.key==='Escape')$('#sidebar').classList.remove('open')});window.addEventListener('hashchange',()=>{const n=location.hash.slice(1);if(n!==view)navigate(n)});
if(window.mermaid)mermaid.initialize({startOnLoad:false,securityLevel:'strict',theme:'base',themeVariables:{fontFamily:'Be Vietnam Pro, Arial, sans-serif',fontSize:'16px',primaryColor:'#f3f6ec',primaryTextColor:'#516448',primaryBorderColor:'#c9d6bc',lineColor:'#a1b28e',secondaryColor:'#faf2e8',tertiaryColor:'#f3f5ed',background:'#ffffff',mainBkg:'#f3f6ec',nodeBorder:'#c9d6bc',clusterBkg:'#fafbf7',edgeLabelBackground:'#fafbf7'},flowchart:{curve:'basis',htmlLabels:false,nodeSpacing:30,rankSpacing:45,useMaxWidth:false},class:{useMaxWidth:false}});
navigate(location.hash.slice(1)||'cinema');

window.AtlasBridge={openCode,navigate};
